import { Component, OnInit } from '@angular/core';
import { ItemsService } from './items.service';

@Component({
  selector: 'app-items',
  template: '<ul><li *ngFor="let i of items">{{ i.nombre }}</li></ul>'
})
export class ItemsComponent implements OnInit {
  items: any[] = [];

  constructor(private itemsService: ItemsService) {}

  ngOnInit() {
    this.itemsService.getItems();
  }
}

candidates.expected_answer:
Falta la llamada a .subscribe(). Los Observables que devuelve HttpClient son perezosos (cold): la petición no se envía hasta que alguien se suscribe, así que getItems() se ejecuta pero nunca llega ninguna respuesta y 'items' sigue vacío. La corrección es suscribirse y asignar los datos recibidos:

ngOnInit() {
  this.itemsService.getItems().subscribe(data => this.items = data);
}

