import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Item } from './item.model';

@Injectable({ providedIn: 'root' })
export class ItemsService {
  constructor(private http: HttpClient) {}

  getItems() {
    this.http.get<Item[]>('/api/items');
  }
}

candidates.expected_answer:
Al método getItems() le falta la palabra clave 'return'. La llamada a this.http.get(...) se ejecuta pero su Observable se descarta, por lo que el método devuelve undefined y el componente falla al intentar .subscribe() sobre undefined (algo como "Cannot read properties of undefined (reading 'subscribe')"). Corrección:

getItems() {
  return this.http.get<Item[]>('/api/items');
}

